#!/usr/bin/env python3
"""Mapa do 2º turno de 2026 (Presidente) por estado: Lula x Flávio Bolsonaro.

ARQUIVO ÚNICO, só biblioteca padrão do Python 3.9+ (nenhum pacote para instalar).
Baixa os resultados ao vivo da API pública do TSE, CONFERE os dados e grava uma página HTML
completa (mapa + ranking + tabela), que abre em qualquer navegador, sem internet depois de gerada.

Uso:
    python3 mapa_turno2_standalone.py                  # grava mapa_2turno.html na pasta atual
    python3 mapa_turno2_standalone.py saida.html       # grava em outro arquivo
    python3 mapa_turno2_standalone.py --verificar      # só baixa, confere e imprime o resumo (não grava)

De onde vêm os dados (sem login):
    https://resultados.tse.jus.br/oficial/ele2026/6258/dados/<uf>/<uf>-c0001-e006258-u.json
    <uf> = sigla em minúsculas dos 27 estados + "br" (Brasil) + "zz" (exterior) = 29 arquivos.
    6258 = eleição "Federal, 2º turno" (o 1º turno de Presidente é 6257).

Conferências automáticas (o script para com erro se falharem):
    1. cada arquivo tem exatamente 2 candidatos: 13 (nome com LULA) e 22 (nome com BOLSONARO);
    2. a soma dos 27 estados + exterior fecha com o total do Brasil (se não fechar, a página
       mostra um aviso no rodapé e o --verificar sai com código 1).

Dentro deste arquivo estão embutidos: o TEMPLATE da página (HTML+CSS+JS) e os CONTORNOS dos
estados (GEO_JSON). Origem dos contornos: click_that_hood (derivado do IBGE), projetados e
simplificados (ver docs/COMO_FOI_FEITO_O_MAPA.md do projeto Mail Center).

Regras de interação da página (mouse, toque, teclado) e formato dos números: ver o guia
docs/COMO_FOI_FEITO_O_MAPA.md. Resumo: passar o mouse/foco destaca o estado com um contorno em
camada própria (nunca reordenar no DOM um estado que pode estar focado); clicar fixa; Enter/Espaço
seleciona; números em pt-BR (votos 64.256.232; % com 2 casas e vírgula; margem em pp com 1 casa).
"""
import json
import sys
import time
import urllib.request
from concurrent.futures import ThreadPoolExecutor

ELEICAO = "6258"
BASE = "https://resultados.tse.jus.br/oficial/ele2026"
UFS = ["AC", "AL", "AP", "AM", "BA", "CE", "DF", "ES", "GO", "MA", "MT", "MS", "MG", "PA",
       "PB", "PR", "PE", "PI", "RJ", "RN", "RS", "RO", "RR", "SC", "SP", "SE", "TO"]


class ErroTSE(Exception):
    pass


def _num(txt) -> float:
    try:
        return float(str(txt).replace(",", "."))
    except ValueError:
        return 0.0


def baixar(url: str) -> dict:
    """GET + JSON, com até 3 tentativas (o TSE devolve 403/5xx esporádico sob carga)."""
    ultimo = None
    for tentativa in range(3):
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "mapa-turno2/1.0"})
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except Exception as exc:  # noqa: BLE001
            ultimo = exc
            time.sleep(0.8 * (tentativa + 1))
    raise ErroTSE(f"TSE não respondeu ({url.rsplit('/', 1)[-1]}): {ultimo}")


def url_arquivo(chave: str) -> str:
    c = chave.lower()
    return f"{BASE}/{ELEICAO}/dados/{c}/{c}-c0001-e00{ELEICAO}-u.json"


def ler(dados: dict, chave: str) -> dict:
    """Lula (13) e Flávio (22) de um arquivo; confere número e nome para nunca trocar os candidatos."""
    nomes, votos = {}, {}
    for agr in dados["carg"][0].get("agr", []):
        for par in agr.get("par", []):
            for c in par.get("cand", []):
                votos[c["n"]] = int(c.get("vap") or 0)
                nomes[c["n"]] = c.get("nm", "").upper()
    if set(votos) != {"13", "22"} or "LULA" not in nomes["13"] or "BOLSONARO" not in nomes["22"]:
        raise ErroTSE(f"Candidatos inesperados no arquivo de {chave}: {nomes}")
    v, e, s = dados.get("v", {}), dados.get("e", {}), dados.get("s", {})
    return {
        "lula": votos["13"], "flavio": votos["22"],
        "brancos": int(v.get("vb") or 0), "nulos": int(v.get("tvn") or 0),
        "compar": int(e.get("c") or 0), "eleitorado": int(e.get("te") or 0),
        "comparecimento_pct": _num(e.get("pcn") or e.get("pc")),
        "secoes_pct": _num(s.get("pst")), "hora": dados.get("ht", ""), "data": dados.get("dt", ""),
    }


def coletar() -> dict:
    """Votos de Lula e Flávio por UF + Brasil + exterior, e a conferência dos totais."""
    chaves = UFS + ["BR", "ZZ"]
    with ThreadPoolExecutor(max_workers=6) as pool:
        lidos = dict(zip(chaves, pool.map(lambda k: ler(baixar(url_arquivo(k)), k), chaves)))
    br, zz = lidos["BR"], lidos["ZZ"]
    res = {u: {k: lidos[u][k] for k in ("lula", "flavio", "brancos", "nulos", "compar", "eleitorado")} for u in UFS}
    dif_l = br["lula"] - (sum(res[u]["lula"] for u in UFS) + zz["lula"])
    dif_f = br["flavio"] - (sum(res[u]["flavio"] for u in UFS) + zz["flavio"])
    return {
        "geo": json.loads(GEO_JSON),
        "res": res,
        "br": {
            "lula": br["lula"], "flavio": br["flavio"], "brancos": br["brancos"], "nulos": br["nulos"],
            "compar": br["compar"], "comparecimento_pct": br["comparecimento_pct"],
            "secoes_pct": min(x["secoes_pct"] for x in lidos.values()),
            "hora": br["hora"], "data": br["data"],
        },
        "ext": {"lula": zz["lula"], "flavio": zz["flavio"]},
        "verificacao": {"ok": dif_l == 0 and dif_f == 0, "dif_lula": dif_l, "dif_flavio": dif_f},
    }


def pagina(dados: dict) -> str:
    """Página HTML completa, com os dados embutidos no lugar de __DATA__."""
    js = json.dumps(dados, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    return ('<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width, initial-scale=1"></head>'
            '<body style="margin:0">' + TEMPLATE.replace("__DATA__", js) + "</body></html>")


def main(argv):
    so_verificar = "--verificar" in argv
    args = [a for a in argv if not a.startswith("--")]
    dados = coletar()
    b, ver = dados["br"], dados["verificacao"]
    pt = lambda n: f"{n:,}".replace(",", ".")  # 64256232 -> 64.256.232
    print(f"Lula {pt(b['lula'])} x Flávio {pt(b['flavio'])} (arquivo {b['data']} {b['hora']}, "
          f"{b['secoes_pct']:.2f}% das seções apuradas)")
    print("Conferência (estados + exterior = Brasil):", "OK" if ver["ok"] else f"FALHOU {ver}")
    if so_verificar:
        return 0 if ver["ok"] else 1
    saida = args[0] if args else "mapa_2turno.html"
    with open(saida, "w", encoding="utf-8") as f:
        f.write(pagina(dados))
    print("Gravado em", saida)
    return 0 if ver["ok"] else 1


